import{_ as e,a as o,b as a,c as r}from"./chunks/spp_polozky4.BMlxLrUn.js";import{_ as n}from"./chunks/spp_polozky3.BRDJgjmN.js";import{_ as s,o as i,c,aa as u}from"./chunks/framework.BAs_AphD.js";const y=JSON.parse('{"title":"Entering Subcontractor Work Statements","description":"","frontmatter":{"title":"Entering Subcontractor Work Statements","wiki":"en:performedworks:subcontractor_actions"},"headers":[],"relativePath":"en/performedworks/subcontractor_actions.md","filePath":"en/performedworks/subcontractor_actions.md","lastUpdated":1794388980000}'),p={name:"en/performedworks/subcontractor_actions.md"};function l(h,t,d,m,g,f){return i(),c("div",null,[...t[0]||(t[0]=[u('<h1 id="entering-subcontractor-work-statements" tabindex="-1">Entering Subcontractor Work Statements <a class="header-anchor" href="#entering-subcontractor-work-statements" aria-label="Permalink to &quot;Entering Subcontractor Work Statements&quot;">​</a></h1><h2 id="proposal" tabindex="-1">Proposal <a class="header-anchor" href="#proposal" aria-label="Permalink to &quot;Proposal&quot;">​</a></h2><p>The Proposed Quantity and Proposed Price columns can be edited by a user who has the Subcontractor Works Proposal permission, provided that the Measurement Report is in the Draft status or does not yet exist for the given period. Values can be entered by typing a number into the quantity or amount column.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Consumption can also be entered as a percentage. If the &quot;%&quot; or &quot;p&quot; symbol is entered after the number, the entered value is interpreted as a percentage and converted to a quantity.</p><p>Consumption can also be entered in bulk, as described in a separate section of the Help.</p></div><img src="'+e+'" alt="" width="1200" loading="lazy"><p>Once the proposal for the Performed Works for the given period has been completed, the subcontractor submits the Measurement Report to the contractor for approval using the following button:</p><figure class="shot" style="--w:200px;"><img src="'+o+'" alt="" width="200" loading="lazy"></figure><p>This also causes the Status, Invoiced Quantity, and Invoiced Price columns to be displayed in the window. These fields cannot be edited by the subcontractor and are therefore for informational purposes only.</p><h2 id="approval" tabindex="-1">Approval <a class="header-anchor" href="#approval" aria-label="Permalink to &quot;Approval&quot;">​</a></h2><p>The contractor representative can change item statuses in several ways:</p><ul><li><p>Individually by selecting a status from the list (any status can be selected)</p></li><li><p>Individually using keyboard shortcuts. The shortcuts differ depending on the language version. The following key combinations can be used in the Czech and Slovak versions:</p></li></ul><figure class="shot" style="--w:20px;"></figure><p>Approved Alt + S Rejected Alt + X In Negotiation Alt + V Change Alt + Z Draft Alt + N</p><ul><li><p>In bulk for selected items (the procedure is described in the &quot;SPP Window, Bulk Operations&quot; section of the Help).</p></li><li><p>By changing the Measurement Report status to &quot;Approved&quot; and subsequently confirming it in the verification report.</p></li></ul><p>The contractor representative can also edit the quantity or price in the Invoiced Quantity or Invoiced Price columns. This operation changes the item status to &quot;Change&quot;. Such an item is considered &quot;approved with changes&quot; and is therefore treated as resolved.</p><p>If the user sets the Invoiced Quantity or price of an item to zero, its status changes to &quot;Rejected&quot;. Conversely, changing the status to &quot;Rejected&quot; sets the Invoiced Quantity and Invoiced Price to zero. Such items are also considered resolved for approval purposes.</p><img src="'+n+'" alt="" width="1200" loading="lazy"><p>If the contractor representative considers all items to be resolved, they change the Measurement Report status by clicking the Approve button.</p><figure class="shot" style="--w:250px;"><img src="'+a+'" alt="" width="250" loading="lazy"></figure><p>If the contractor representative needs the subcontractor to make changes to some items, they change the Measurement Report status to &quot;Return for Correction&quot;. When the status is changed, items with the &quot;Draft&quot; status are moved to the &quot;In Negotiation&quot; status.</p><h2 id="proposal-change" tabindex="-1">Proposal Change <a class="header-anchor" href="#proposal-change" aria-label="Permalink to &quot;Proposal Change&quot;">​</a></h2><p>If the Measurement Report is in the &quot;Proposal Change&quot; status, the subcontractor can edit the &quot;Changed Quantity&quot; column only for items that are in the &quot;In Negotiation&quot; status, or for items for which no &quot;Proposed Quantity&quot; has yet been entered.</p><img src="'+r+'" alt="" width="1200" loading="lazy"><p>After entering the changes, the subcontractor submits the Measurement Report to the contractor representative for approval again.</p>',24)])])}const _=s(p,[["render",l]]);export{y as __pageData,_ as default};
